"""Local CLI workflow for generating and safely saving search configs."""

from __future__ import annotations

import os
import re
import shlex
import uuid
from collections.abc import Callable
from pathlib import Path
from typing import Any

import click
import yaml

from ..client import PaperclipClient

_SOURCE_SUFFIXES = {".md", ".txt"}
_WORKFLOW_FIELDS = ("version", "name", "description", "steps", "output")


class ConfigGenerationError(click.ClickException):
    """A local input or output error while generating a workflow."""


def resolve_proposal(value: str) -> tuple[str, str | None]:
    """Read an existing Markdown/text path; otherwise preserve literal input."""
    candidate = Path(value).expanduser()
    try:
        is_source_file = (
            candidate.suffix.lower() in _SOURCE_SUFFIXES and candidate.is_file()
        )
    except OSError:
        # Long or otherwise invalid filesystem names are still valid literal
        # proposal text.
        is_source_file = False
    if is_source_file:
        try:
            return candidate.read_text(encoding="utf-8"), candidate.name
        except OSError as exc:
            raise ConfigGenerationError(f"Could not read {candidate}: {exc}") from exc
    return value, None


def _safe_filename(name: Any) -> str:
    slug = re.sub(r"[^a-z0-9]+", "-", str(name or "search-workflow").lower())
    return slug.strip("-") or "search-workflow"


def _workflow_only(value: Any) -> dict[str, Any]:
    if not isinstance(value, dict):
        raise ConfigGenerationError("The server returned an invalid workflow.")
    missing = [
        field
        for field in ("version", "name", "steps", "output")
        if field not in value
    ]
    if missing:
        raise ConfigGenerationError(
            f"The generated workflow is missing: {', '.join(missing)}"
        )
    return {field: value[field] for field in _WORKFLOW_FIELDS if field in value}


def _validate_output_path(path: Path, *, force: bool) -> Path:
    target = path.expanduser().resolve()
    if not target.parent.is_dir():
        raise ConfigGenerationError(f"Output directory does not exist: {target.parent}")
    if not force and (target.exists() or target.is_symlink()):
        raise ConfigGenerationError(
            f"Output already exists: {target}. Use --force to replace it."
        )
    return target


def write_workflow(path: Path, workflow: dict[str, Any], *, force: bool) -> None:
    """Atomically publish YAML, refusing replacement unless explicitly forced."""
    target = _validate_output_path(path, force=force)
    temporary = target.with_name(f".{target.name}.{os.getpid()}.{uuid.uuid4().hex}.tmp")
    try:
        with temporary.open("x", encoding="utf-8") as handle:
            yaml.safe_dump(
                workflow,
                handle,
                sort_keys=False,
                allow_unicode=True,
            )
            handle.flush()
            os.fsync(handle.fileno())
        if force:
            os.replace(temporary, target)
        else:
            try:
                os.link(temporary, target)
            except FileExistsError as exc:
                raise ConfigGenerationError(
                    f"Output already exists: {target}. Use --force to replace it."
                ) from exc
    finally:
        temporary.unlink(missing_ok=True)


def _print_notes(result: dict[str, Any]) -> None:
    assumptions = result.get("assumptions") or []
    risks = result.get("unresolved_risks") or []
    diagnostics = (result.get("review") or {}).get("diagnostics") or []
    warnings = [
        item.get("message")
        for item in diagnostics
        if isinstance(item, dict) and item.get("severity") == "warning"
    ]
    for heading, items in (
        ("Assumptions", assumptions),
        ("Unresolved risks", risks),
        ("Review warnings", warnings),
    ):
        if items:
            click.echo(f"\n{heading}:")
            for item in items:
                click.echo(f"  - {item}")


def build_generate_search_config_command(
    client_factory: Callable[[], PaperclipClient],
) -> click.Command:
    @click.command("generate-search-config")
    @click.argument("proposal")
    @click.option("-o", "--output", type=click.Path(path_type=Path))
    @click.option("--force", is_flag=True, help="Replace an existing output file.")
    def command(proposal: str, output: Path | None, force: bool) -> None:
        """Turn proposal text or a .md/.txt file into workflow YAML."""
        proposal_text, source_name = resolve_proposal(proposal)
        if not proposal_text.strip():
            raise ConfigGenerationError("The proposal is empty.")
        if output is not None:
            _validate_output_path(output, force=force)
        result = client_factory().generate_search_config(
            proposal_text,
            source_name=source_name,
        )
        workflow = _workflow_only(result.get("config"))
        destination = output or Path(f"{_safe_filename(workflow['name'])}.yaml")
        write_workflow(destination, workflow, force=force)
        click.echo(f"Wrote {destination.resolve()}")
        _print_notes(result)
        # Match the path normalization used by write_workflow(). Quoting an
        # unexpanded leading ``~`` prevents the shell from expanding it.
        command_destination = destination.expanduser()
        quoted_destination = shlex.quote(str(command_destination))
        click.echo(
            f"\nRun: paperclip search --config {quoted_destination} --save-as "
            f"{_safe_filename(workflow['name'])}"
        )

    return command
